 *
 * @param address the raw address value from the request, or {@code null}
 * @return the normalized address (empty string when {@code address} is {@code null} or blank)
 */
private String normalizeAddress(String address) {
    if (address == null) {
        return "";
    }
    String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
    if (collapsed.isEmpty()) {
        return "";
    }
    String[] tokens = collapsed.split(" ");
    for (int i = 0; i < tokens.length; i++) {
        switch (tokens[i]) {
            case "ST" -> tokens[i] = "STREET";
            case "RD" -> tokens[i] = "ROAD";
            case "AVE" -> tokens[i] = "AVENUE";
            default -> { }
        }
    }
    return String.join(" ", tokens);
}

/**
 * Rejects an owner create whose {@code identityKey} exactly matches a non-deleted existing owner's.
 * The identity key - the SHA-256 hex digest over the owner's normalized telephone, lower-cased email
 * (empty when none) and the Soundex code of its last name, joined by {@code '|'} - is the single
 * derived value used for duplicate detection; owners flagged deleted are ignored. Only a whole-key
 * match is a conflict, so two owners with the same last name and postcode but different telephones
 * have different keys and are both allowed; only an owner whose entire key is identical is a
 * duplicate.
 *
 * @param owner the owner being created, with its telephone, email and last name already resolved
 * @throws DuplicateOwnerIdentityException if another non-deleted owner already has this exact identity key
 */
private void rejectDuplicateIdentity(Owner owner) {
    String identityKey = owner.getIdentityKey();
    boolean inUse = this.clinicService.findAllOwners().stream()
        .filter(existing -> !existing.isDeleted())
        .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
    if (inUse) {
        throw new DuplicateOwnerIdentityException(identityKey);
    }
}

/**
 * Flags an owner being created as a possible (soft) duplicate. A soft match is an existing owner
 * whose last name shares this owner's Soundex code and whose postcode matches, yet whose
 * {@code identityKey} differs; such an owner is not a hard duplicate (its whole identity key
 * differs) and is still created. When at least one soft match exists, {@code possibleDuplicate} is
 * set true and {@code possibleDuplicateOf} to the lowest-id match; otherwise {@code possibleDuplicate}
 * is false and {@code possibleDuplicateOf} is left unset.
 * <p>
 * A declared household member - an owner that acknowledged sharing an existing household via
 * {@code sharesHousehold} - is never flagged: having deliberately joined the household it is not a
 * suspected duplicate, so {@code possibleDuplicate} is set false without inspecting other owners.
 *
 * @param owner the owner being created, with its last name, postcode, email and normalized
 *        telephone resolved
 * @param declaredHouseholdMember whether the owner joined an existing household by acknowledging it
 */
private void applyPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
    if (declaredHouseholdMember) {
        owner.setPossibleDuplicate(false);
        return;
    }
    String soundex = Owner.soundex(owner.getLastName());
    String postcode = owner.getPostcode();
    String identityKey = owner.getIdentityKey();
    Owner match = null;
    if (postcode != null && !postcode.isBlank()) {
        match = this.clinicService.findAllOwners().stream()
            .filter(existing -> !existing.isDeleted())
            .filter(existing -> Owner.soundex(existing.getLastName()).equals(soundex))
            .filter(existing -> postcode.equals(existing.getPostcode()))
            .filter(existing -> !identityKey.equals(existing.getIdentityKey()))
            .min(java.util.Comparator.comparing(Owner::getId))
            .orElse(null);
    }
    if (match != null) {
        owner.setPossibleDuplicate(true);
        owner.setPossibleDuplicateOf(match.getId());
    } else {
        owner.setPossibleDuplicate(false);
    }
}

/**
 * Maps an owner to its DTO, first populating the owner's {@link Owner#getHouseholdMemberCount()
 * household member count} for the response.
 *
 * @param owner the owner to map
 * @return the mapped owner DTO
 */
private OwnerDto toOwnerDto(Owner owner) {
    owner.setHouseholdMemberCount(countHouseholdMembers(owner));
    return ownerMapper.toOwnerDto(owner);
}

/**
 * Counts the members of the given owner's household - the owners that share this owner's
 * {@code householdId}, including the owner itself. An owner with no household ({@code householdId}
 * is {@code null}) is its own sole member, so the count is one.
 *
 * @param owner the owner whose household is being sized
 * @return the number of owners sharing this owner's household (one when it has no household)
 */
private int countHouseholdMembers(Owner owner) {
    String householdId = owner.getHouseholdId();
    if (householdId == null) {
        return 1;
    }
    return (int) this.clinicService.findAllOwners().stream()
        .filter(existing -> householdId.equals(existing.getHouseholdId()))
        .count();
}

/**
 * Caps the membership level of an owner being created so it can never exceed one above the current
 * maximum membership level among the other members of its household. The ceiling stored is that
 * maximum plus one; the owner's derived {@link Owner#getMembershipLevel() membership level} is then
 * never reported above it. An owner that joined no existing household - it has no {@code householdId}
 * or is the sole member of its household - is left uncapped so no ceiling applies.
 *
 * @param owner the owner being created, with its {@code householdId} already resolved
 */
private void applyMembershipLevelCeiling(Owner owner) {
    String householdId = owner.getHouseholdId();
    if (householdId == null) {
        return;
    }
    OptionalInt maxLevel = this.clinicService.findAllOwners().stream()
        .filter(existing -> !existing.isDeleted())
        .filter(existing -> householdId.equals(existing.getHouseholdId()))
        .mapToInt(this::currentMembershipLevel)
        .max();
    if (maxLevel.isPresent()) {
        owner.setMembershipLevelCeiling(maxLevel.getAsInt() + 1);
    }
}

/**
 * The membership level an existing owner currently reports, computed the same way as for a response
 * by first populating its {@link Owner#getHouseholdMemberCount() household member count}.
 *
 * @param member the existing household member whose membership level is needed
 * @return the member's current membership level
 */
private int currentMembershipLevel(Owner member) {
    member.setHouseholdMemberCount(countHouseholdMembers(member));
    return member.getMembershipLevel();
}

/**
 * Applies the household rule to an owner being created. A household is the set of owners sharing a
 * last name and a postcode: the {@code householdId} is derived deterministically from the
 * normalized last name and the postcode (see {@link #generateHouseholdId(String, String)}), so two
 * owners with the same last name and postcode always resolve to the same identifier and belong to
 * the same household automatically - no acknowledgement is needed to create the link.
 * <p>
 * When the owner supplies a postcode its {@code householdId} is always assigned; an owner with no
 * postcode belongs to no household and is left without an identifier. Joining an existing household
 * is not itself a conflict: hard duplicate detection is handled solely by the identity key (see
 * {@link #rejectDuplicateIdentity(Owner)}), so two members of one household with different
 * telephones are both created. An owner that explicitly acknowledges an existing household via
 * {@code sharesHousehold} is reported as a declared member so it is not flagged as a possible
 * duplicate.
 *
 * @param owner the owner being created
 * @param sharesHousehold the request's shared-household acknowledgement, or {@code null} when absent
 * @return {@code true} when the owner joined an existing household as a declared member, otherwise
 *         {@code false}
 */
private boolean applyHousehold(Owner owner, Boolean sharesHousehold) {
    String postcode = owner.getPostcode();
    if (postcode == null || postcode.isBlank()) {
        return false;
    }
    String lastName = normalizeHouseholdField(owner.getLastName());
    String householdId = generateHouseholdId(lastName, postcode);
    owner.setHouseholdId(householdId);
    boolean hasExistingMember = this.clinicService.findAllOwners().stream()
        .filter(existing -> !existing.isDeleted())
        .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
    return hasExistingMember && Boolean.TRUE.equals(sharesHousehold);
}

/**
 * Builds the stable identifier shared by the members of one household. It is derived from the fixed
 * {@code 'V2'} version tag, the normalized last name and the postcode, so every owner sharing a last
 * name and postcode resolves to the same value - the first 12 upper-case hex characters of the
 * SHA-256 digest of the three fields joined by a single '|'. Mixing in the version tag rederives the
 * household id for version 2, so no version-1 household id is produced again.
 *
 * @param normalizedLastName the household's last name, already normalized for comparison
 * @param postcode the household's postcode
 * @return the shared household identifier
 */
private String generateHouseholdId(String normalizedLastName, String postcode) {
    String key = Owner.IDENTITY_VERSION_TAG + '|' + normalizedLastName + '|' + postcode;
    try {
        byte[] digest = MessageDigest.getInstance("SHA-256")
            .digest(key.getBytes(StandardCharsets.UTF_8));
        StringBuilder hex = new StringBuilder();
        for (byte b : digest) {
            hex.append(String.format("%02X", b));
            if (hex.length() >= 12) {
                break;
            }
        }
        return hex.substring(0, 12);
    } catch (NoSuchAlgorithmException e) {
        throw new IllegalStateException("SHA-256 is required but unavailable", e);
    }
}

